class BanxicoMatrixApiConnector:
    def __init__(self, settings, trace=None) -> None:
        self.settings = settings
        self.config = settings.raw["sources"]["banxico"]
        self.trace = trace

        timeout_seconds = max(30, int(self.config.get("timeout_ms", 90000)) // 1000)
        configured_pool_maxsize = int(self.config.get("api_http_pool_maxsize", 4))
        configured_parallelism = int(self.config.get("api_parallelism", 4))
        pool_maxsize = max(1, configured_pool_maxsize, configured_parallelism)
        connect_timeout_seconds = int(self.config.get("api_http_connect_timeout_seconds", 15))

        self.http = BanxicoHttpClient(
            timeout_seconds=timeout_seconds,
            connect_timeout_seconds=connect_timeout_seconds,
            pool_maxsize=pool_maxsize,
        )
        self.topology_cache = BanxicoTopologyCache(
            settings.database_path,
            enabled=bool(self.config.get("api_topology_cache_enabled", True)),
        )
        self.cache_mode = str(self.config.get("api_topology_cache_mode", "members_only")).strip().lower()
        self.cache_frontier_enabled = bool(
            self.config.get(
                "api_topology_cache_use_frontier",
                self.cache_mode in {"frontier", "frontier_experimental"},
            )
        )
        self.cache_persist_frontier = bool(
            self.config.get("api_topology_cache_persist_frontier", self.cache_frontier_enabled)
        )
        self.cache_skip_persist_if_unchanged = bool(
            self.config.get("api_topology_cache_skip_persist_if_unchanged", True)
        )

    def run_job(self, job: BanxicoJob) -> Path:
        result = self.run_jobs([job])[0]
        if not result.ok or result.output_path is None:
            raise RuntimeError(result.error_message or f"Falló el job {job.job_id}")
        return result.output_path

    def run_jobs(self, jobs: list[BanxicoJob]) -> list[BanxicoJobResult]:
        if self.trace:
            self.trace.event("api_connector.run_jobs_called", jobs=len(jobs))
        try:
            return asyncio.run(self._run_jobs(jobs))
        finally:
            self.http.close()

    async def _run_jobs(self, jobs: list[BanxicoJob]) -> list[BanxicoJobResult]:
        if not jobs:
            return []

        first_metric = jobs[0].metric
        if any(job.metric != first_metric for job in jobs):
            raise ValueError("Todos los jobs del batch Banxico deben compartir el mismo metric")

        if first_metric != "value":
            raise ValueError("El conector Banxico API privado solo está habilitado para metric='value'")

        url = self.config["value_matrix_url"]
        results: list[BanxicoJobResult] = []

        if self.trace:
            self.trace.set_meta(api_metric=first_metric, api_jobs=len(jobs))

        with (self.trace.stage("api.playwright_session") if self.trace else _nullcontext()):
            async with async_playwright() as p:
                browser = await p.chromium.launch(headless=bool(self.config.get("headless", True)))
                context = await browser.new_context()
                page = await context.new_page()
                page.set_default_timeout(int(self.config.get("timeout_ms", 90000)))

                try:
                    if self.trace:
                        self.trace.event("api.bootstrap_start", url=url)
                    with (self.trace.stage("api.bootstrap_template") if self.trace else _nullcontext()):
                        template = await self._bootstrap_template(page, url, metric=first_metric)
                    # Para el extractor exhaustivo no dependemos del payload live capturado;
                    # usamos una plantilla estática conocida y una sesión live.
                    static_payload = self._static_payload_template(first_metric)
                    template = _CapturedTemplate(
                        headers=template.headers,
                        payload=static_payload,
                        payload_builder=BanxicoPayloadBuilder.from_payload(static_payload),
                    )
                    self.http.update_session_headers(template.headers)

                    if self.trace:
                        self.trace.event("api.job_loop_start", jobs=len(jobs))

                    for job in jobs:
                        output_path = self.settings.bronze_dir / f"{job.job_id}.xlsx"
                        screenshot_path = self.settings.log_dir / f"{job.job_id}_api_failure.png"
                        try:
                            if self.trace:
                                self.trace.event("api.job_start", job_id=job.job_id)
                            with (self.trace.stage("api.extract_job_to_excel", job_id=job.job_id) if self.trace else _nullcontext()):
                                await asyncio.to_thread(self._extract_job_to_excel, template, job, output_path)
                            LOGGER.info("Archivo Banxico reconstruido por API privada: %s", output_path)
                            results.append(BanxicoJobResult(job=job, output_path=output_path))
                            if self.trace:
                                self.trace.incr("api_jobs_ok", 1)
                                self.trace.event("api.job_finished", job_id=job.job_id, output_path=str(output_path))
                        except urllib.error.HTTPError as exc:
                            if exc.code == 401:
                                LOGGER.warning("401 Banxico para %s; refrescando sesión y reintentando una vez", job.job_id)
                                if self.trace:
                                    self.trace.incr("api_http_401_refresh", 1)
                                    self.trace.event("api.job_401_refresh", job_id=job.job_id)
                                template = await self._bootstrap_template(page, url, metric=first_metric, force_reload=True)
                                refreshed_static_payload = self._static_payload_template(first_metric)
                                template = _CapturedTemplate(
                                    headers=template.headers,
                                    payload=refreshed_static_payload,
                                    payload_builder=BanxicoPayloadBuilder.from_payload(refreshed_static_payload),
                                )
                                self.http.update_session_headers(template.headers)
                                try:
                                    await asyncio.to_thread(self._extract_job_to_excel, template, job, output_path)
                                    LOGGER.info("Archivo Banxico reconstruido tras refresh: %s", output_path)
                                    results.append(BanxicoJobResult(job=job, output_path=output_path))
                                    if self.trace:
                                        self.trace.incr("api_jobs_ok", 1)
                                        self.trace.event("api.job_finished", job_id=job.job_id, output_path=str(output_path))
                                    continue
                                except Exception as retry_exc:
                                    await self._try_screenshot(page, screenshot_path)
                                    results.append(
                                        BanxicoJobResult(
                                            job=job,
                                            error_message=str(retry_exc),
                                            error_traceback=traceback.format_exc(),
                                        )
                                    )
                                    if self.trace:
                                        self.trace.incr("api_jobs_failed", 1)
                                        self.trace.event("api.job_exception", job_id=job.job_id, error=str(retry_exc))
                                    continue
                            await self._try_screenshot(page, screenshot_path)
                            results.append(
                                BanxicoJobResult(
                                    job=job,
                                    error_message=str(exc),
                                    error_traceback=traceback.format_exc(),
                                )
                            )
                            if self.trace:
                                self.trace.incr("api_jobs_failed", 1)
                                self.trace.event("api.job_exception", job_id=job.job_id, error=str(exc))
                        except Exception as exc:
                            await self._try_screenshot(page, screenshot_path)
                            results.append(
                                BanxicoJobResult(
                                    job=job,
                                    error_message=str(exc),
                                    error_traceback=traceback.format_exc(),
                                )
                            )
                            if self.trace:
                                self.trace.incr("api_jobs_failed", 1)
                                self.trace.event("api.job_exception", job_id=job.job_id, error=str(exc))
                finally:
                    await browser.close()
        return results

    async def _try_screenshot(self, page: Page, screenshot_path: Path) -> None:
        try:
            await page.screenshot(path=str(screenshot_path), full_page=True)
            LOGGER.error("Screenshot de fallo Banxico API guardado en: %s", screenshot_path)
        except Exception:
            LOGGER.exception("No se pudo guardar screenshot del fallo Banxico API")

    async def _bootstrap_template(
            self,
            page: Page,
            url: str,
            *,
            metric: str,
            force_reload: bool = False,
    ) -> _CapturedTemplate:
        if force_reload:
            await page.goto("about:blank")
            await page.wait_for_timeout(200)

        loop = asyncio.get_running_loop()
        queue: asyncio.Queue[_CapturedTemplate] = asyncio.Queue()
        last_infra_headers: dict[str, str] = {}

        async def maybe_capture_request(request) -> None:
            nonlocal last_infra_headers
            try:
                request_url = str(getattr(request, "url", "") or "")
                if "infraEntryPoint" not in request_url:
                    return

                headers = await self._extract_request_headers(request)
                if headers:
                    headers_norm = {str(k): str(v) for k, v in headers.items()}
                    if any(k.lower() == "pyramidembeddedauth" for k in headers_norm):
                        last_infra_headers = headers_norm

                post_data = self._extract_request_post_data(request)
                if not post_data:
                    return
                payload = json.loads(post_data)
                query = payload.get("query", {})
                if query.get("service") != "IQueryService" or query.get("method") != "runQuery":
                    return
                if not last_infra_headers:
                    last_infra_headers = await self._extract_request_headers(request)
                await queue.put(_CapturedTemplate(headers=last_infra_headers, payload=payload))
            except Exception:
                LOGGER.debug("Request infraEntryPoint ignorado durante bootstrap", exc_info=True)

        async def maybe_capture_response(response) -> None:
            try:
                response_url = str(getattr(response, "url", "") or "")
                if "infraEntryPoint" not in response_url:
                    return
                request = response.request
                await maybe_capture_request(request)
            except Exception:
                LOGGER.debug("Respuesta infraEntryPoint ignorada durante bootstrap", exc_info=True)

        def on_request(request) -> None:
            loop.create_task(maybe_capture_request(request))

        def on_response(response) -> None:
            loop.create_task(maybe_capture_response(response))

        context = page.context
        context.on("request", on_request)
        context.on("response", on_response)
        try:
            await page.goto(url, wait_until="load")
            await page.wait_for_timeout(2500)

            timeout_seconds = max(20.0, float(int(self.config.get("timeout_ms", 90000)) / 1000.0))
            phase_timeout = min(12.0, timeout_seconds / 2.0)

            for attempt in range(2):
                try:
                    template = await asyncio.wait_for(queue.get(), timeout=phase_timeout)
                    LOGGER.info("Bootstrap Banxico capturado desde request live (%s)", url)
                    if self.trace:
                        self.trace.incr("bootstrap_live_capture", 1)
                        self.trace.event("bootstrap_live_capture")
                    return template
                except asyncio.TimeoutError:
                    if attempt == 0:
                        LOGGER.warning(
                            "Bootstrap Banxico no capturó runQuery al primer intento; recargando la página una vez"
                        )
                        if self.trace:
                            self.trace.incr("bootstrap_reload_once", 1)
                            self.trace.event("bootstrap_reload_once")
                        try:
                            await page.reload(wait_until="load")
                        except Exception:
                            await page.goto(url, wait_until="load")
                        await page.wait_for_timeout(2500)
                        continue

            if last_infra_headers:
                LOGGER.warning("Usando payload base estático Banxico; solo se capturó la sesión/headers live")
                if self.trace:
                    self.trace.incr("bootstrap_static_payload_fallback", 1)
                    self.trace.event("bootstrap_static_payload_fallback")
                return _CapturedTemplate(headers=last_infra_headers, payload=self._static_payload_template(metric))

            raise RuntimeError("No se pudo capturar un payload base válido de IQueryService.runQuery")
        finally:
            context.remove_listener("request", on_request)
            context.remove_listener("response", on_response)

    @staticmethod
    def _extract_request_post_data(request) -> str | None:
        try:
            value = getattr(request, "post_data", None)
            if callable(value):
                value = value()
            return value
        except Exception:
            return None

    @staticmethod
    async def _extract_request_headers(request) -> dict[str, str]:
        all_headers = getattr(request, "all_headers", None)
        if callable(all_headers):
            try:
                return await all_headers()
            except Exception:
                pass
        headers = getattr(request, "headers", None)
        if callable(headers):
            try:
                return headers()
            except Exception:
                pass
        return {}

    @staticmethod
    def _normalize_identifier(value: str) -> str:
        text = unicodedata.normalize("NFKD", value or "")
        text = "".join(ch for ch in text if not unicodedata.combining(ch))
        text = re.sub(r"\s+", " ", text).strip().lower()
        return text

    @classmethod
    def _identifier_tokens(cls, value: str) -> list[str]:
        text = unicodedata.normalize("NFKD", value or "")
        text = "".join(ch for ch in text if not unicodedata.combining(ch))
        text = re.sub(r"[^0-9A-Za-z]+", " ", text).strip().lower()
        return [token for token in text.split() if token]

    @classmethod
    def _tokens_loosely_match(cls, target: str, candidate: str) -> bool:
        target_tokens = [token for token in cls._identifier_tokens(target) if len(token) >= 3]
        candidate_tokens = cls._identifier_tokens(candidate)
        if not target_tokens or not candidate_tokens:
            return False

        def token_match(left: str, right: str) -> bool:
            if left == right:
                return True
            if len(left) >= 5 and len(right) >= 5 and (left.startswith(right) or right.startswith(left)):
                return True
            common = 0
            for a, b in zip(left, right):
                if a != b:
                    break
                common += 1
            return common >= 5

        return all(any(token_match(target_token, cand_token) for cand_token in candidate_tokens) for target_token in
                   target_tokens)

    def _locate_prom_selection(
            self,
            qom: dict[str, Any],
            target: str,
    ) -> tuple[str, dict[str, Any]]:
        prom = qom.get("promSelections")
        if not isinstance(prom, dict):
            raise KeyError("qom.promSelections")

        target_norm = self._normalize_identifier(target)
        for key, selection in prom.items():
            candidates = [str(key)]
            if isinstance(selection, dict):
                model_attr = selection.get("modelAttribute")
                if isinstance(model_attr, dict) and model_attr.get("column"):
                    candidates.append(str(model_attr["column"]))
                elements = selection.get("elements")
                if isinstance(elements, list) and elements:
                    value = elements[0].get("value")
                    if value:
                        candidates.append(str(value))
            if any(
                    self._normalize_identifier(candidate).startswith(target_norm)
                    or self._tokens_loosely_match(target, candidate)
                    for candidate in candidates
            ):
                return str(key), selection

        raise KeyError(target)

    def _set_prom_selection_member(
            self,
            qom: dict[str, Any],
            *,
            target: str,
            member_caption: str,
    ) -> None:
        try:
            _key, selection = self._locate_prom_selection(qom, target)
        except KeyError:
            prom = qom.setdefault("promSelections", {})
            if not isinstance(prom, dict):
                raise
            selection = {
                "promSelectionType": 0,
                "elements": [
                    {
                        "elementSelectionType": 0,
                        "value": f"{target}.[{member_caption}]",
                        "elementFunction": None,
                    }
                ],
                "numbers": [],
                "strings": [],
                "valueSelections": [],
                "modelAttribute": {"column": target, "type": 3},
            }
            prom[target] = selection

        model_attr = selection.get("modelAttribute") if isinstance(selection, dict) else None
        column = None
        if isinstance(model_attr, dict):
            column = model_attr.get("column")
        if not column:
            column = target

        elements = selection.get("elements")
        if not isinstance(elements, list) or not elements:
            elements = [{"elementSelectionType": 0, "value": None, "elementFunction": None}]
            selection["elements"] = elements

        current_value = elements[0].get("value")
        if isinstance(current_value, str) and current_value.count(".[") >= 2:
            prefix = current_value.rsplit(".[", 1)[0]
        else:
            prefix = str(column)

        existing_leaf = ""
        if isinstance(current_value, str) and current_value.endswith("]") and ".[" in current_value:
            existing_leaf = current_value.rsplit(".[", 1)[1][:-1]

        if existing_leaf:
            existing_norm = self._normalize_identifier(existing_leaf)
            replacements = {
                "exportacion": existing_leaf,
                "importacion": existing_leaf,
            }
            target_norm = self._normalize_identifier(member_caption)
            if target_norm in replacements:
                if "exportacion" in existing_norm:
                    member_caption = existing_leaf if target_norm == "exportacion" else existing_leaf.replace("Export",
                                                                                                              "Import")
                elif "importacion" in existing_norm:
                    member_caption = existing_leaf if target_norm == "importacion" else existing_leaf.replace("Import",
                                                                                                              "Export")

        elements[0]["value"] = f"{prefix}.[{member_caption}]"

    def _static_payload_template(self, metric: str) -> dict[str, Any]:
        seed_payloads = self._static_seed_payloads(metric)
        if not seed_payloads:
            raise RuntimeError(
                "No se pudo capturar un payload live y no hay plantilla estática para metric distinto de value"
            )
        return copy.deepcopy(seed_payloads[0])

    def _decode_embedded_payload(self, encoded: str) -> dict[str, Any]:
        return json.loads(gzip.decompress(base64.b64decode(encoded)).decode("utf-8"))

    def _decode_embedded_response(self, encoded: str) -> dict[str, Any]:
        return json.loads(gzip.decompress(base64.b64decode(encoded)).decode("utf-8"))

    def _static_chapter_response_seeds(self, metric: str) -> dict[str, list[dict[str, Any]]]:
        """Respuestas 200 capturadas manualmente como semillas de hechos.

        Estas respuestas no se reenvían al backend: se integran localmente como
        evidencia inicial para el mes/flujo de referencia. Esto evita fallos de
        replay provocados por payloads copiados desde DevTools con nombres únicos
        dañados por codificación/escaping de cURL.
        """
        if metric.lower() != "value":
            return {}
        result: dict[str, list[dict[str, Any]]] = {}
        for chapter_unique, encoded_responses in _SEED_VALUE_RESPONSES_BY_CHAPTER_B64.items():
            result[chapter_unique] = [self._decode_embedded_response(encoded) for encoded in encoded_responses]
        return result

    def _static_seed_payloads(self, metric: str) -> list[dict[str, Any]]:
        if metric.lower() != "value":
            return []
        payloads = [
            self._decode_embedded_payload(_SEED_VALUE_PAYLOAD_AMPLIADO_B64),
            self._decode_embedded_payload(_SEED_VALUE_PAYLOAD_ORIGINAL_B64),
        ]
        for payload in payloads:
            qom = payload["query"]["arguments"][0]["qom"]
            self._set_prom_selection_member(qom, target="[Fecha].[Meses]", member_caption="Enero 2022")
            self._set_prom_selection_member(
                qom,
                target="[Tipo Operación].[Tipos de Operación]",
                member_caption="Exportación",
            )
            qom["subsets"]["data"]["modelAttribute"]["column"] = "[Measures].[Valor en dólares]"
        return payloads

    def _static_chapter_seed_payloads(self, metric: str) -> dict[str, list[dict[str, Any]]]:
        if metric.lower() != "value":
            return {}
        result: dict[str, list[dict[str, Any]]] = {}
        for chapter_unique, encoded_payloads in _SEED_VALUE_PAYLOADS_BY_CHAPTER_B64.items():
            payloads = [self._decode_embedded_payload(encoded) for encoded in encoded_payloads]
            for payload in payloads:
                qom = payload["query"]["arguments"][0]["qom"]
                self._set_prom_selection_member(qom, target="[Fecha].[Meses]", member_caption="Enero 2022")
                self._set_prom_selection_member(
                    qom,
                    target="[Tipo Operación].[Tipos de Operación]",
                    member_caption="Exportación",
                )
                qom["subsets"]["data"]["modelAttribute"]["column"] = "[Measures].[Valor en dólares]"
            result[chapter_unique] = payloads
        return result

    def _query_job(
            self,
            template: _CapturedTemplate,
            job: BanxicoJob,
            *,
            payload_override: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        payload = copy.deepcopy(payload_override if payload_override is not None else template.payload)
        qom = payload["query"]["arguments"][0]["qom"]

        flow_label = "Exportación" if job.flow_code.upper() == "EXPORT" else "Importación"

        self._set_prom_selection_member(qom, target="[Fecha].[Meses]", member_caption=job.month_label)
        self._set_prom_selection_member(
            qom,
            target="[Tipo Operación].[Tipos de Operación]",
            member_caption=flow_label,
        )

        max_attempts = max(1, int(self.config.get("api_http_retries", 4)))
        retry_delay = float(self.config.get("api_http_retry_delay_seconds", 1.5))

        try:
            response = self.http.request_json(
                url=INFRA_ENTRYPOINT_URL,
                payload=payload,
                max_attempts=max_attempts,
                retry_delay_seconds=retry_delay,
            )

            if self.trace:
                self.trace.incr("api_http_requests", 1)
                self.trace.add_value("api_http_elapsed_seconds", response.elapsed_seconds)
                self.trace.add_value("api_http_attempts_total", response.attempt)
                self.trace.event(
                    "api_http_request_ok",
                    status=response.status,
                    elapsed_seconds=response.elapsed_seconds,
                    attempt=response.attempt,
                )

            text = self._decode_http_body(
                response.data,
                response.headers.get("Content-Encoding", ""),
            )
            return json.loads(text)

        except urllib.error.HTTPError as exc:
            if self.trace:
                self.trace.incr("api_http_http_errors", 1)
                self.trace.event(
                    "api_http_http_error",
                    code=getattr(exc, "code", None),
                    error=str(exc),
                )
            raise

        except (urllib3.exceptions.HTTPError, TimeoutError, ConnectionError, OSError) as exc:
            if self.trace:
                self.trace.incr("api_http_transient_failures", 1)
                self.trace.event("api_http_transient_failure", error=str(exc))
                if "timed out" in str(exc).lower():
                    self.trace.incr("api_http_timeouts", 1)
            raise

    @staticmethod
    def _decode_http_body(raw_bytes: bytes, content_encoding: str) -> str:
        encoding = (content_encoding or "").lower()

        if raw_bytes[:2] == b"\x1f\x8b":
            try:
                return gzip.decompress(raw_bytes).decode("utf-8")
            except Exception:
                pass

        if "gzip" in encoding:
            return gzip.decompress(raw_bytes).decode("utf-8")

        if "deflate" in encoding:
            try:
                return zlib.decompress(raw_bytes).decode("utf-8")
            except zlib.error:
                return zlib.decompress(raw_bytes, -zlib.MAX_WBITS).decode("utf-8")

        if "br" in encoding:
            if brotli is None:
                raise RuntimeError("La respuesta Banxico vino en br pero no está disponible el módulo brotli")
            return brotli.decompress(raw_bytes).decode("utf-8")

        return raw_bytes.decode("utf-8")

    def _extract_job_to_excel(self, template: _CapturedTemplate, job: BanxicoJob, output_path: Path) -> None:
        facts, members, countries = self._collect_tree_facts(template, job)
        self._write_fact_matrix_excel(facts=facts, members=members, countries=countries, job=job,
                                      output_path=output_path)

    def _collect_tree_facts(
            self,
            template: _CapturedTemplate,
            job: BanxicoJob,
    ) -> tuple[dict[tuple[str, str], float], dict[str, _MemberRecord], dict[str, str]]:
        base_payload = template.payload
        root_products = self._extract_root_product_values(base_payload)
        if not root_products:
            root_products = list(_STATIC_ROOT_PRODUCTS)

        members_by_unique: dict[str, _MemberRecord] = self._seed_static_members()
        facts: dict[tuple[str, str], float] = {}
        countries: dict[str, str] = {}

        chapter_uniques = self._static_chapter_uniques()
        LOGGER.info("Banxico API: usando andamiaje estático de capítulos = %d", len(chapter_uniques))

        query_budget = {"count": 0, "max": int(self.config.get("max_api_queries", 2200))}
        log_every = max(1, int(self.config.get("api_log_every", 25)))
        parallelism = max(1, int(self.config.get("api_parallelism", 4)))
        if self.trace:
            self.trace.incr("api_parallelism_configured", parallelism)

        cache_snapshot = self.topology_cache.load_snapshot(
            metric=job.metric,
            expected_chapters=chapter_uniques,
            include_frontier=self.cache_frontier_enabled,
        )
        min_frontier_nodes = int(self.config.get("api_topology_cache_min_frontier", 100))
        min_chapter_coverage = int(
            self.config.get("api_topology_cache_min_chapter_coverage", max(1, len(chapter_uniques) // 2))
        )
        cache_usable = self.cache_frontier_enabled and cache_snapshot.is_usable(
            min_frontier_nodes=min_frontier_nodes,
            min_chapter_coverage=min_chapter_coverage,
        )
        if self.trace:
            self.trace.incr("api_topology_cache_members_loaded", cache_snapshot.members_count)
            self.trace.incr("api_topology_cache_frontier_loaded", cache_snapshot.frontier_count)
            self.trace.incr("api_topology_cache_chapter_coverage", cache_snapshot.chapter_coverage)
            if cache_snapshot.members_count:
                self.trace.incr("api_topology_cache_members_used", 1)
            if not self.cache_frontier_enabled:
                self.trace.incr("api_topology_cache_frontier_disabled", 1)
            if cache_usable:
                self.trace.incr("api_topology_cache_used", 1)
                self.trace.incr("api_topology_cache_frontier_used", 1)

        if cache_snapshot.members:
            for unique_name, payload in cache_snapshot.members.items():
                members_by_unique.setdefault(unique_name, self._member_from_cache_entry(payload))

        if cache_usable:
            LOGGER.info(
                "Banxico API: usando caché persistente con frontera (%d miembros, %d nodos frontera, %d capítulos)",
                cache_snapshot.members_count,
                cache_snapshot.frontier_count,
                cache_snapshot.chapter_coverage,
            )
        elif cache_snapshot.members_count:
            LOGGER.info(
                "Banxico API: usando caché segura de topología estructural (%d miembros); la frontera persistida está deshabilitada",
                cache_snapshot.members_count,
            )
        else:
            LOGGER.info(
                "Banxico API: caché de topología vacía, insuficiente o deshabilitada (%d miembros, %d nodos frontera, %d capítulos)",
                cache_snapshot.members_count,
                cache_snapshot.frontier_count,
                cache_snapshot.chapter_coverage,
            )

        seed_payloads = self._static_seed_payloads(job.metric)
        if seed_payloads:
            LOGGER.info(
                "Banxico API: ejecutando %d consultas semilla amplias antes del recorrido fino",
                len(seed_payloads),
            )
        for idx, seed_payload in enumerate(seed_payloads, start=1):
            if query_budget["count"] >= query_budget["max"]:
                break
            try:
                query_budget["count"] += 1
                response_obj = self._query_job(template, job, payload_override=seed_payload)
                parsed = self._response_to_facts(response_obj)
                self._merge_response_state(parsed, members_by_unique, facts, countries)
                LOGGER.info(
                    "Banxico API: semilla %d/%d -> productos con valor acumulados = %d",
                    idx,
                    len(seed_payloads),
                    len({product_unique for product_unique, _country in facts}),
                )
            except Exception as exc:
                LOGGER.warning("Banxico API: la consulta semilla %d falló: %s", idx, exc)

        use_local_response_seeds = (
                job.metric.lower() == "value"
                and job.flow_code.upper() == "EXPORT"
                and self._normalize_identifier(job.month_label) == "enero 2022"
        )
        chapter_response_seeds = (
            self._static_chapter_response_seeds(job.metric) if use_local_response_seeds else {}
        )
        if chapter_response_seeds:
            LOGGER.info(
                "Banxico API: integrando %d respuestas semilla locales por capítulo",
                len(chapter_response_seeds),
            )
            for chapter_unique, encoded_payloads in chapter_response_seeds.items():
                for encoded_payload in encoded_payloads:
                    try:
                        parsed = self._response_to_facts(self._decode_seed_response(encoded_payload))
                        self._merge_response_state(parsed, members_by_unique, facts, countries)
                    except Exception as exc:
                        LOGGER.warning(
                            "Banxico API: no se pudo integrar la semilla local del capítulo %s: %s",
                            self._caption_from_unique(chapter_unique),
                            exc,
                        )

        chapter_seed_stats = self._chapter_seed_stats(chapter_uniques, members_by_unique, facts)
        confirmed_frontier_by_chapter: dict[str, set[str]] = defaultdict(set)
        rediscovery_targets: dict[str, list[str]] = defaultdict(list)

        if cache_usable and cache_snapshot.frontier_by_chapter and query_budget["count"] < query_budget["max"]:
            cache_frontier_tasks = self._build_cached_frontier_tasks(
                cache_snapshot.frontier_by_chapter,
                chapter_uniques=chapter_uniques,
                members_by_unique=members_by_unique,
            )
            if self.trace:
                self.trace.incr("api_topology_cache_frontier_tasks", len(cache_frontier_tasks))

            with ThreadPoolExecutor(max_workers=parallelism, thread_name_prefix="banxico-cache") as executor:
                for batch in self._chunked(cache_frontier_tasks, parallelism):
                    if query_budget["count"] >= query_budget["max"]:
                        break
                    if not batch:
                        continue

                    remaining_budget = query_budget["max"] - query_budget["count"]
                    if remaining_budget <= 0:
                        break
                    batch = batch[:remaining_budget]
                    if not batch:
                        break

                    futures = {}
                    members_snapshot = dict(members_by_unique)
                    for task in batch:
                        future = executor.submit(
                            self._expand_single_node,
                            template=template,
                            job=job,
                            base_payload=base_payload,
                            current_unique=task.current_unique,
                            members_by_unique=members_snapshot,
                        )
                        futures[future] = task

                    if self.trace:
                        self.trace.incr("api_parallel_batches", 1)
                        self.trace.incr("api_parallel_tasks", len(batch))

                    for future in as_completed(futures):
                        task = futures[future]
                        outcome = future.result()
                        if outcome.queried:
                            query_budget["count"] += 1

                        if outcome.parsed is not None:
                            self._merge_response_state(outcome.parsed, members_by_unique, facts, countries)

                        if outcome.transient_error:
                            rediscovery_targets[task.chapter_unique].append(task.current_unique)
                            continue

                        if outcome.next_targets:
                            rediscovery_targets[task.chapter_unique].extend(outcome.next_targets)
                        elif outcome.queried:
                            confirmed_frontier_by_chapter[task.chapter_unique].add(task.current_unique)

            for chapter_unique in chapter_uniques:
                if not cache_snapshot.frontier_by_chapter.get(chapter_unique):
                    rediscovery_targets[chapter_unique].append(chapter_unique)

        else:
            for chapter_unique in chapter_uniques:
                rediscovery_targets[chapter_unique].append(chapter_unique)

        rediscovery_targets = {
            chapter_unique: self._sort_member_uniques(
                self._dedupe_preserve(values),
                members_by_unique,
            )
            for chapter_unique, values in rediscovery_targets.items()
            if values
        }

        if self.trace:
            self.trace.incr("api_topology_cache_rediscovery_chapters", len(rediscovery_targets))

        if rediscovery_targets and query_budget["count"] < query_budget["max"]:
            planner = BanxicoFrontierPlanner(
                chapter_uniques=[ch for ch in chapter_uniques if ch in rediscovery_targets],
                chapter_seed_stats=chapter_seed_stats,
                log_every=log_every,
                limit_missing=int(self.config.get("max_api_queries_per_chapter_missing", 24)),
                limit_sparse=int(self.config.get("max_api_queries_per_chapter_sparse", 14)),
                limit_rich=int(self.config.get("max_api_queries_per_chapter_rich", 8)),
                initial_targets=rediscovery_targets,
            )

            with ThreadPoolExecutor(max_workers=parallelism, thread_name_prefix="banxico-api") as executor:
                while query_budget["count"] < query_budget["max"] and planner.has_pending_work():
                    remaining_budget = query_budget["max"] - query_budget["count"]
                    batch = planner.build_batch(
                        remaining_budget=remaining_budget,
                        max_tasks=parallelism,
                    )
                    if not batch:
                        break

                    if self.trace:
                        self.trace.incr("api_parallel_batches", 1)
                        self.trace.incr("api_parallel_tasks", len(batch))

                    futures = {}
                    for task in batch:
                        if task.should_log:
                            member = members_by_unique.get(task.chapter_unique)
                            caption = member.caption if member else task.chapter_unique
                            LOGGER.info(
                                "Banxico API: expandiendo capítulo %d/%d -> %s",
                                task.position,
                                task.total_chapters,
                                caption,
                            )

                        members_snapshot = dict(members_by_unique)
                        future = executor.submit(
                            self._expand_single_node,
                            template=template,
                            job=job,
                            base_payload=base_payload,
                            current_unique=task.current_unique,
                            members_by_unique=members_snapshot,
                        )
                        futures[future] = task

                    progress = False
                    for future in as_completed(futures):
                        task = futures[future]
                        outcome = future.result()

                        if outcome.queried:
                            query_budget["count"] += 1
                            progress = True

                        if outcome.parsed is not None:
                            self._merge_response_state(outcome.parsed, members_by_unique, facts, countries)

                        planner.apply_result(
                            task,
                            queried=outcome.queried,
                            next_targets=outcome.next_targets,
                        )

                        if outcome.transient_error:
                            continue
                        if outcome.queried and not outcome.next_targets:
                            confirmed_frontier_by_chapter[task.chapter_unique].add(task.current_unique)

                    if not progress:
                        break

        if query_budget["count"] >= query_budget["max"]:
            LOGGER.warning(
                "Banxico API: se alcanzó el límite de %d consultas; se detiene la extracción restante",
                query_budget["max"],
            )

        if facts:
            try:
                self._persist_topology_cache(
                    metric=job.metric,
                    members_by_unique=members_by_unique,
                    chapter_uniques=chapter_uniques,
                    frontier_by_chapter=confirmed_frontier_by_chapter,
                    persist_frontier=self.cache_persist_frontier,
                    cache_snapshot=cache_snapshot,
                )
            except Exception as exc:
                LOGGER.warning("Banxico API: no se pudo persistir la caché de topología: %s", exc)

        return facts, members_by_unique, countries

    @staticmethod
    def _member_from_cache_entry(payload: dict[str, Any]) -> _MemberRecord:
        return _MemberRecord(
            index=-1,
            parent_index=None,
            level=payload.get("level"),
            caption=payload.get("caption") or payload.get("unique_name") or "",
            unique_name=payload.get("unique_name") or "",
            raw_type=payload.get("raw_type") or "",
            raw_parts=list(payload.get("raw_parts") or []),
            parent_unique_name=payload.get("parent_unique_name"),
        )

    def _build_cached_frontier_tasks(
            self,
            frontier_by_chapter: dict[str, list[str]],
            *,
            chapter_uniques: list[str],
            members_by_unique: dict[str, _MemberRecord],
    ) -> list[FrontierTask]:
        tasks: list[FrontierTask] = []
        total_chapters = len(chapter_uniques)
        for pos, chapter_unique in enumerate(chapter_uniques, start=1):
            frontier_values = self._sort_member_uniques(
                self._dedupe_preserve(frontier_by_chapter.get(chapter_unique, [])),
                members_by_unique,
            )
            for idx, current_unique in enumerate(frontier_values):
                tasks.append(
                    FrontierTask(
                        chapter_unique=chapter_unique,
                        current_unique=current_unique,
                        position=pos,
                        total_chapters=total_chapters,
                        leaf_hits=0,
                        fact_hits=0,
                        should_log=(idx == 0 and (pos == 1 or pos % max(1, int(self.config.get("api_log_every", 25))) == 0 or pos == total_chapters)),
                    )
                )
        return tasks

    def _persist_topology_cache(
            self,
            *,
            metric: str,
            members_by_unique: dict[str, _MemberRecord],
            chapter_uniques: list[str],
            frontier_by_chapter: dict[str, set[str]],
            persist_frontier: bool,
            cache_snapshot: CachedTopologySnapshot | None = None,
    ) -> None:
        chapter_set = set(chapter_uniques)
        members_rows: list[dict[str, Any]] = []
        edges_rows: list[dict[str, Any]] = []

        for unique_name, member in members_by_unique.items():
            if not self._is_product_member(member):
                continue
            chapter_unique = self._infer_member_chapter_unique(
                members_by_unique,
                unique_name,
                chapter_set,
            )
            members_rows.append(
                {
                    "unique_name": unique_name,
                    "caption": member.caption,
                    "parent_unique_name": member.parent_unique_name,
                    "level": member.level,
                    "raw_type": member.raw_type,
                    "raw_parts_json": json.dumps(member.raw_parts, ensure_ascii=False),
                    "chapter_unique": chapter_unique,
                }
            )
            if member.parent_unique_name:
                edges_rows.append(
                    {
                        "parent_unique_name": member.parent_unique_name,
                        "child_unique_name": unique_name,
                        "chapter_unique": chapter_unique,
                    }
                )

        frontier_rows: list[dict[str, Any]] = []
        if persist_frontier:
            for chapter_unique, values in frontier_by_chapter.items():
                for unique_name in self._sort_member_uniques(self._dedupe_preserve(list(values)), members_by_unique):
                    member = members_by_unique.get(unique_name)
                    frontier_rows.append(
                        {
                            "metric": metric,
                            "chapter_unique": chapter_unique,
                            "frontier_unique": unique_name,
                            "level": member.level if member else None,
                        }
                    )

        should_persist, persist_info = self.topology_cache.should_persist(
            snapshot=cache_snapshot,
            members_rows=members_rows,
            frontier_rows=frontier_rows,
            persist_frontier=persist_frontier,
        )

        if self.cache_skip_persist_if_unchanged and not should_persist:
            if self.trace:
                self.trace.incr("api_topology_cache_persist_skipped_noop", 1)
                if not persist_info.get("members_changed", False):
                    self.trace.incr("api_topology_cache_members_unchanged", len(members_rows))
                if persist_frontier and not persist_info.get("frontier_changed", False):
                    self.trace.incr("api_topology_cache_frontier_unchanged", len(frontier_rows))
            LOGGER.info(
                "Banxico API: caché de topología sin cambios (%d miembros, %d frontera); se omite persistencia",
                len(members_rows),
                len(frontier_rows),
            )
            return

        self.topology_cache.persist(
            metric=metric,
            members_rows=members_rows,
            edges_rows=edges_rows,
            frontier_rows=frontier_rows,
            chapters_count=len(chapter_uniques),
            persist_frontier=persist_frontier,
        )

        if self.trace:
            self.trace.incr("api_topology_cache_members_persisted", len(members_rows))
            self.trace.incr("api_topology_cache_frontier_persisted", len(frontier_rows))
            if should_persist:
                self.trace.incr("api_topology_cache_persist_writes", 1)

    def _infer_member_chapter_unique(
            self,
            members_by_unique: dict[str, _MemberRecord],
            unique_name: str,
            chapter_uniques: set[str],
    ) -> str | None:
        current = unique_name
        while current:
            if current in chapter_uniques:
                return current
            member = members_by_unique.get(current)
            if member is None:
                return None
            current = member.parent_unique_name
        return None

    def _chapter_seed_stats(
            self,
            chapter_uniques: list[str],
            members_by_unique: dict[str, _MemberRecord],
            facts: dict[tuple[str, str], float],
    ) -> dict[str, tuple[int, int]]:
        stats: dict[str, tuple[int, int]] = {}
        products_with_facts = {product_unique for product_unique, _country_unique in facts}
        for chapter_unique in chapter_uniques:
            fact_hits = 0
            leaf_hits = 0
            for product_unique in products_with_facts:
                if not self._belongs_to_branch(members_by_unique, product_unique, chapter_unique):
                    continue
                fact_hits += 1
                member = members_by_unique.get(product_unique)
                if member and member.caption and re.match(r"^\d{10}", member.caption.strip()):
                    leaf_hits += 1
            stats[chapter_unique] = (leaf_hits, fact_hits)
        return stats

    def _prioritize_chapter_phases(
            self,
            chapter_uniques: list[str],
            chapter_seed_stats: dict[str, tuple[int, int]],
    ) -> tuple[list[str], list[str]]:
        phase_one = [
            ch
            for ch in chapter_uniques
            if chapter_seed_stats.get(ch, (0, 0))[0] == 0
               or chapter_seed_stats.get(ch, (0, 0))[1] <= 1
        ]
        phase_two = [ch for ch in chapter_uniques if ch not in phase_one]

        phase_one = sorted(phase_one, key=lambda ch: chapter_seed_stats.get(ch, (0, 0)))
        phase_two = sorted(phase_two, key=lambda ch: chapter_seed_stats.get(ch, (0, 0)))
        return phase_one, phase_two

    def _expand_single_node(
            self,
            *,
            template: _CapturedTemplate,
            job: BanxicoJob,
            base_payload: dict[str, Any],
            current_unique: str,
            members_by_unique: dict[str, _MemberRecord],
    ) -> _ExpansionOutcome:
        current_member = members_by_unique.get(current_unique)
        if current_member and current_member.level is not None and current_member.level >= 5:
            return _ExpansionOutcome(next_targets=[], queried=False)

        explicit_products = [self._root_product_unique(members_by_unique)]
        explicit_products.extend(self._ancestor_chain(members_by_unique, current_unique))
        explicit_products.append(current_unique)

        if template.payload_builder is not None:
            payload = template.payload_builder.build_product_payload(
                base_payload,
                explicit_products=explicit_products,
                descendants_products=[current_unique],
            )
        else:
            payload = self._build_product_payload(
                base_payload,
                explicit_products=explicit_products,
                descendants_products=[current_unique],
            )

        try:
            response_obj = self._query_job(template, job, payload_override=payload)
            parsed = self._response_to_facts(response_obj)
        except (urllib.error.URLError, TimeoutError, ConnectionError, OSError) as exc:
            LOGGER.warning(
                "Banxico API: se omitió temporalmente el nodo %s por fallo de red: %s",
                self._caption_from_unique(current_unique),
                exc,
            )
            return _ExpansionOutcome(next_targets=[], queried=True, transient_error=str(exc))

        combined_members = dict(members_by_unique)
        combined_members.update(parsed.members_by_unique)

        immediate_children = [
            unique_name
            for unique_name, member in parsed.members_by_unique.items()
            if self._is_product_member(member) and member.parent_unique_name == current_unique
        ]
        immediate_children = self._sort_member_uniques(
            self._dedupe_preserve(immediate_children),
            combined_members,
        )
        if not immediate_children:
            return _ExpansionOutcome(next_targets=[], queried=True, parsed=parsed)

        visible_parent_set = {
            member.parent_unique_name
            for member in parsed.members_by_unique.values()
            if self._is_product_member(member) and member.parent_unique_name
        }
        saturated = len(parsed.members_by_unique) >= int(self.config.get("member_saturation_threshold", 1700))
        frontier_set = set(parsed.frontier_products)

        next_targets: list[str] = []
        for child_unique in immediate_children:
            child = combined_members.get(child_unique)
            if child is None or child.level is None or child.level >= 5:
                continue
            has_visible_children = child_unique in visible_parent_set

            if saturated:
                next_targets.append(child_unique)
                continue
            if child_unique in frontier_set:
                next_targets.append(child_unique)
                continue
            if child.raw_type == "1a":
                next_targets.append(child_unique)
                continue
            if not has_visible_children and child.level <= 3:
                next_targets.append(child_unique)

        next_targets = self._sort_member_uniques(
            self._dedupe_preserve(next_targets),
            combined_members,
        )
        return _ExpansionOutcome(next_targets=next_targets, queried=True, parsed=parsed)

    def _build_product_payload(
            self,
            base_payload: dict[str, Any],
            *,
            explicit_products: list[str],
            descendants_products: list[str],
    ) -> dict[str, Any]:
        builder = BanxicoPayloadBuilder.from_payload(base_payload)
        return builder.build_product_payload(
            base_payload,
            explicit_products=explicit_products,
            descendants_products=descendants_products,
        )

    def _sync_product_selection_mirrors(
            self,
            payload: dict[str, Any],
            selection_list: list[dict[str, Any]],
    ) -> None:
        query = payload.get("query", {})
        arguments = query.get("arguments", [])
        if not arguments:
            return
        argument0 = arguments[0]
        qsm = argument0.get("qsm")
        if not isinstance(qsm, dict):
            return
        for item in qsm.get("dropZoneItems", []):
            if not isinstance(item, dict):
                continue
            if item.get("hierarchyUniqueName") != "[Productos].[TIGIE]":
                continue
            qom_selection = item.get("qomSelection")
            if not isinstance(qom_selection, dict):
                continue
            qom_selection["elementSelectionList"] = copy.deepcopy(selection_list)

    @staticmethod
    def _make_explicit_selection(unique_name: str) -> dict[str, Any]:
        return {
            "elementSelectionType": 0,
            "value": unique_name,
            "elementFunction": None,
            "deselect": False,
        }

    @staticmethod
    def _make_descendants_selection(unique_name: str) -> dict[str, Any]:
        return {
            "elementSelectionType": 1,
            "elementFunction": {
                "elementFunctionType": 8,
                "arguments": [unique_name],
                "caption": None,
                "includeCalculatedMembers": True,
            },
            "value": None,
            "deselect": False,
        }

    def _extract_root_product_values(self, payload: dict[str, Any]) -> list[str]:
        qom = payload["query"]["arguments"][0]["qom"]
        product_attr = qom["columns"]["attributes"][0]
        values: list[str] = []
        for element in product_attr.get("elementSelectionList", []):
            if not isinstance(element, dict):
                continue
            if element.get("elementSelectionType") != 0:
                continue
            value = element.get("value")
            if not isinstance(value, str) or not value.startswith("[Productos].[TIGIE]."):
                continue
            if not self._is_root_scaffold_value(value):
                continue
            values.append(value)

        values = self._dedupe_preserve(values)
        if values:
            return values

        return list(_STATIC_ROOT_PRODUCTS)

    @staticmethod
    def _is_root_scaffold_value(unique_name: str) -> bool:
        return (
                "Todos los productos" in unique_name
                or "Sección " in unique_name
                or "Sin Sección" in unique_name
        )

    def _static_chapter_uniques(self) -> list[str]:
        return list(_STATIC_CHAPTER_PARENT_MAP.keys())

    @staticmethod
    def _chapter_code_from_unique(unique_name: str) -> str:
        match = re.search(r"\[(\d{2})\s", unique_name)
        return match.group(1) if match else unique_name

    def _seed_static_members(self) -> dict[str, _MemberRecord]:
        members: dict[str, _MemberRecord] = {}
        root_unique = _STATIC_ROOT_PRODUCTS[0]
        members[root_unique] = _MemberRecord(
            index=-1,
            parent_index=None,
            level=0,
            caption=self._caption_from_unique(root_unique),
            unique_name=root_unique,
            raw_type="1b",
            raw_parts=[],
            parent_unique_name=None,
        )

        for root_unique_name in _STATIC_ROOT_PRODUCTS[1:]:
            level = 1
            members[root_unique_name] = _MemberRecord(
                index=-1,
                parent_index=None,
                level=level,
                caption=self._caption_from_unique(root_unique_name),
                unique_name=root_unique_name,
                raw_type="1b",
                raw_parts=[],
                parent_unique_name=_STATIC_ROOT_PRODUCTS[0],
            )

        for chapter_unique, parent_unique in _STATIC_CHAPTER_PARENT_MAP.items():
            members[chapter_unique] = _MemberRecord(
                index=-1,
                parent_index=None,
                level=2,
                caption=self._caption_from_unique(chapter_unique),
                unique_name=chapter_unique,
                raw_type="1b",
                raw_parts=[],
                parent_unique_name=parent_unique,
            )
        return members

    @staticmethod
    def _caption_from_unique(unique_name: str) -> str:
        match = re.search(r"\[(.*?)\]$", unique_name)
        return match.group(1) if match else unique_name

    def _response_to_facts(self, response_obj: dict[str, Any]) -> _ResponseFacts:
        data = response_obj.get("data")
        if isinstance(data, str):
            data = json.loads(data)
        if not isinstance(data, dict):
            raise ValueError("La respuesta de Banxico no contiene un objeto `data` interpretable")

        members = self._decode_member_map(data["serializedMemberMap"]["memberMapSerialized"])
        members_by_index = {record.index: record for record in members}
        members_by_unique = {record.unique_name: record for record in members if record.unique_name}

        raw_results = data.get("rawResults", [])
        if len(raw_results) < 3:
            raise ValueError("La respuesta Banxico no trae las 3 columnas esperadas en rawResults")

        region_ids = raw_results[0]
        product_ids = raw_results[1]
        values = raw_results[2]
        if not (len(region_ids) == len(product_ids) == len(values)):
            raise ValueError("Las columnas rawResults de Banxico no tienen la misma longitud")

        facts: dict[tuple[str, str], float] = {}
        countries: dict[str, str] = {}
        for region_id, product_id, value in zip(region_ids, product_ids, values):
            parsed_value = self._parse_cell_value(value)
            if parsed_value is None:
                continue
            region_member = members_by_index.get(region_id)
            product_member = members_by_index.get(product_id)
            if region_member is None or product_member is None:
                continue
            if not self._is_country_member(region_member):
                continue
            if not self._is_product_member(product_member):
                continue
            if not region_member.unique_name or not product_member.unique_name:
                continue
            countries[region_member.unique_name] = region_member.caption
            facts[(product_member.unique_name, region_member.unique_name)] = parsed_value

        frontier_products: list[str] = []
        children_by_parent: dict[str, list[_MemberRecord]] = defaultdict(list)
        products_with_facts: set[str] = set()
        for record in members:
            if record.parent_unique_name and self._is_product_member(record):
                children_by_parent[record.parent_unique_name].append(record)

        for product_unique, _country_unique in facts:
            products_with_facts.add(product_unique)

        for record in members:
            if not self._is_product_member(record):
                continue
            if record.level is None or record.level >= 5:
                continue
            if "Todos los productos" in record.caption:
                continue
            if children_by_parent.get(record.unique_name):
                continue

            # raw_type=1a suele marcar frontera colapsada, pero también conviene
            # reintentar nodos agregados que ya traen hechos y siguen sin mostrar hijos.
            if record.raw_type == "1a" or record.unique_name in products_with_facts:
                frontier_products.append(record.unique_name)

        return _ResponseFacts(
            members_by_unique=members_by_unique,
            facts=facts,
            countries=countries,
            frontier_products=self._dedupe_preserve(frontier_products),
        )

    def _merge_response_state(
            self,
            parsed: _ResponseFacts,
            members_by_unique: dict[str, _MemberRecord],
            facts: dict[tuple[str, str], float],
            countries: dict[str, str],
    ) -> None:
        members_by_unique.update(parsed.members_by_unique)
        facts.update(parsed.facts)
        countries.update(parsed.countries)

    def _write_fact_matrix_excel(
            self,
            *,
            facts: dict[tuple[str, str], float],
            members: dict[str, _MemberRecord],
            countries: dict[str, str],
            job: BanxicoJob,
            output_path: Path,
    ) -> None:
        if not facts:
            raise ValueError("La extracción Banxico no produjo celdas país-producto con valor")

        country_uniques = self._sort_country_uniques(countries)
        product_uniques = self._select_output_products(facts, members)
        if not product_uniques or not country_uniques:
            raise ValueError("La extracción Banxico no produjo una matriz país-producto con detalle suficiente")

        metric_caption = "Valor en dólares"
        title = f"Cubo de Información de Comercio Exterior - {metric_caption}"
        flow_label = "Exportación" if job.flow_code.upper() == "EXPORT" else "Importación"

        header = ["TIGIE", *[countries[u] for u in country_uniques]]
        rows: list[list[Any]] = []
        rows.append([title, *([None] * (len(header) - 1))])
        rows.append([flow_label, job.month_label, *([None] * (len(header) - 2))])
        rows.append(header)

        for product_unique in product_uniques:
            member = members[product_unique]
            row = [member.caption]
            for country_unique in country_uniques:
                row.append(facts.get((product_unique, country_unique)))
            rows.append(row)

        df = pd.DataFrame(rows)
        output_path.parent.mkdir(parents=True, exist_ok=True)
        with pd.ExcelWriter(output_path, engine="openpyxl") as writer:
            df.to_excel(writer, index=False, header=False, sheet_name="Tabla")

    def _select_output_products(
            self,
            facts: dict[tuple[str, str], float],
            members: dict[str, _MemberRecord],
    ) -> list[str]:
        products_with_facts = {product_unique for product_unique, _country_unique in facts}

        children_by_parent: dict[str, set[str]] = defaultdict(set)
        for unique_name, record in members.items():
            if not self._is_product_member(record):
                continue
            if record.parent_unique_name:
                children_by_parent[record.parent_unique_name].add(unique_name)

        discovered_detail_leaves: set[str] = set()
        for unique_name, record in members.items():
            if not self._is_product_member(record):
                continue
            if "Todos los productos" in record.caption:
                continue
            if children_by_parent.get(unique_name):
                continue
            if self._is_detail_leaf_product(record):
                discovered_detail_leaves.add(unique_name)

        selected = set(products_with_facts) | discovered_detail_leaves
        for product_unique in list(selected):
            ancestor = members.get(product_unique).parent_unique_name if product_unique in members else None
            while ancestor:
                if ancestor in selected:
                    selected.discard(ancestor)
                ancestor = members.get(ancestor).parent_unique_name if ancestor in members else None
        return self._sort_member_uniques(list(selected), members)

    @staticmethod
    def _is_detail_leaf_product(record: _MemberRecord) -> bool:
        if not record.caption:
            return False
        if re.match(r"^\d{10}\b", record.caption.strip()):
            return True
        return bool(re.search(r"\[\d{10}\b", record.unique_name))

    def _response_to_excel(self, response_obj: dict[str, Any], job: BanxicoJob, output_path: Path) -> None:
        parsed = self._response_to_facts(response_obj)
        self._write_fact_matrix_excel(
            facts=parsed.facts,
            members=parsed.members_by_unique,
            countries=parsed.countries,
            job=job,
            output_path=output_path,
        )

    def _parse_cell_value(self, value: Any) -> float | None:
        if value is None:
            return None
        if isinstance(value, bool):
            return float(value)
        if isinstance(value, (int, float)):
            return float(value)

        text = str(value).strip()
        if not text:
            return None

        normalized = self._normalize_identifier(text)
        null_markers = {
            "na",
            "n/a",
            "null",
            "none",
            "nan",
            "nd",
            "s/d",
            "-",
            "--",
        }
        if normalized in null_markers:
            return None

        text = text.replace(",", "")
        return float(text)

    def _measure_caption(self, data: dict[str, Any], members: list[_MemberRecord]) -> str:
        measures_member_map = data.get("measuresMemberMap")
        if isinstance(measures_member_map, dict) and measures_member_map:
            try:
                first_key = next(iter(measures_member_map.keys()))
                index = int(first_key)
                if 0 <= index < len(members):
                    return members[index].caption or "Valor"
            except Exception:
                pass

        column_map = data.get("columnMap")
        if isinstance(column_map, list) and len(column_map) >= 3:
            caption = column_map[2].get("caption")
            if caption:
                return str(caption)
        return "Valor"

    def _decode_member_map(self, serialized: str) -> list[_MemberRecord]:
        records: list[_MemberRecord] = []
        for idx, raw_record in enumerate(serialized.split("☻")):
            parts = raw_record.split("␞◙")
            parent_raw = parts[1] if len(parts) > 1 else ""
            level_raw = parts[2] if len(parts) > 2 else ""
            caption = parts[3] if len(parts) > 3 else ""
            unique_name = parts[8].rstrip("␞") if len(parts) > 8 else ""
            try:
                parent_index = int(parent_raw) if parent_raw not in {"", "-"} else None
            except ValueError:
                parent_index = None
            try:
                level = int(level_raw) if level_raw not in {"", "-"} else None
            except ValueError:
                level = None
            records.append(
                _MemberRecord(
                    index=idx,
                    parent_index=parent_index,
                    level=level,
                    caption=caption,
                    unique_name=unique_name,
                    raw_type=parts[0] if parts else "",
                    raw_parts=parts,
                )
            )

        for record in records:
            if record.parent_index is None:
                continue
            if 0 <= record.parent_index < len(records):
                parent_unique_name = records[record.parent_index].unique_name
                record.parent_unique_name = parent_unique_name or None
        return records

    @staticmethod
    def _is_product_member(record: _MemberRecord) -> bool:
        return record.unique_name.startswith("[Productos].[TIGIE].")

    @staticmethod
    def _is_country_member(record: _MemberRecord) -> bool:
        return record.unique_name.startswith("[Localización].[Regiones].") and record.level == 2

    def _belongs_to_branch(
            self,
            members_by_unique: dict[str, _MemberRecord],
            candidate_unique: str,
            branch_unique: str,
    ) -> bool:
        current = candidate_unique
        while current:
            if current == branch_unique:
                return True
            current = members_by_unique.get(current).parent_unique_name if current in members_by_unique else None
        return False

    def _ancestor_chain(
            self,
            members_by_unique: dict[str, _MemberRecord],
            unique_name: str,
    ) -> list[str]:
        chain: list[str] = []
        current = members_by_unique.get(unique_name)
        while current and current.parent_unique_name:
            parent = current.parent_unique_name
            chain.append(parent)
            current = members_by_unique.get(parent)
        chain.reverse()
        return chain

    def _root_product_unique(self, members_by_unique: dict[str, _MemberRecord]) -> str:
        for unique_name, member in members_by_unique.items():
            if self._is_product_member(member) and "Todos los productos" in member.caption:
                return unique_name
        default_payload = self._static_payload_template("value")
        roots = self._extract_root_product_values(default_payload)
        return next((value for value in roots if "Todos los productos" in value), roots[0])

    @staticmethod
    def _dedupe_preserve(values: list[str]) -> list[str]:
        seen: set[str] = set()
        ordered: list[str] = []
        for value in values:
            if not value or value in seen:
                continue
            seen.add(value)
            ordered.append(value)
        return ordered

    @staticmethod
    def _chunked(values: list[str], size: int) -> list[list[str]]:
        return [values[i: i + size] for i in range(0, len(values), size)]

    def _sort_country_uniques(self, countries: dict[str, str]) -> list[str]:
        return sorted(countries.keys(), key=lambda key: self._normalize_identifier(countries[key]))

    def _sort_member_uniques(
            self,
            unique_names: list[str],
            members: dict[str, _MemberRecord],
    ) -> list[str]:
        def sort_key(unique_name: str) -> tuple[str, int, str]:
            member = members.get(unique_name)
            caption = (member.caption if member else unique_name).strip()
            match = re.match(r"^(\d{2,10})", caption)
            code = match.group(1) if match else "zzzzzzzzzz"
            return (code, len(code), self._normalize_identifier(caption))

        return sorted(unique_names, key=sort_key)

class _nullcontext:
    def __enter__(self):
        return None

    def __exit__(self, exc_type, exc, tb):
        return False